const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=new URLSearchParams(location.search).get('job'),last='',activeTab='drawing',shownPath='',shownPlayback='',renderedJob='';
$('preview').onload=()=>{$('preview').hidden=false;$('preview-placeholder').hidden=true;};
$('preview').onerror=()=>{$('preview').hidden=true;$('preview-placeholder').hidden=false;$('preview-placeholder').textContent='Preview unavailable. Open the PDF above.';};
function tab(name){activeTab=name;for(const t of ['drawing','path','simulation'])$(t+'-view').hidden=t!==name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));tab('drawing');
$('new').onclick=()=>{selected=null;history.replaceState(null,'',location.pathname);last='';$('empty').hidden=false;$('job').hidden=true;$('file').value='';};
async function upload(file){if(!file)return;$('upload-error').textContent='Uploading…';try{const r=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/pdf','X-Filename':encodeURIComponent(file.name)},body:file}),data=await r.json();if(!r.ok)throw Error(data.error);selected=data.id;history.replaceState(null,'','?job='+selected);last='';$('upload-error').textContent='';await refresh();}catch(e){$('upload-error').textContent=e.message;}}
$('example').onclick=async()=>{const blob=await fetch('examples/bearing-pocket.pdf').then(r=>r.blob());upload(new File([blob],'bearing-pocket.pdf',{type:'application/pdf'}));};
$('file').onchange=()=>upload($('file').files[0]);$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('drag');};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');upload(e.dataTransfer.files[0]);};
function pathPreview(points){if(!points?.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),lo=[Math.min(...xs),Math.min(...ys)],hi=[Math.max(...xs),Math.max(...ys)],scale=Math.min(520/(hi[0]-lo[0]||1),330/(hi[1]-lo[1]||1)),pts=points.map(p=>`${40+(p[0]-lo[0])*scale},${380-(p[1]-lo[1])*scale}`).join(' ');$('toolpath').innerHTML=`<polyline points="${pts}" fill="none" stroke="#4d7950" stroke-width="1"/><text x="20" y="20" font-size="11" fill="#7b8c71">XY · mm · all generated linear movements</text>`;}
function render(s){if(renderedJob!==s.id){renderedJob=s.id;shownPath='';shownPlayback='';$('preview').hidden=true;$('preview').removeAttribute('src');$('preview-placeholder').hidden=false;$('preview-placeholder').textContent='Reading drawing…';$('review').innerHTML='';$('toolpath').innerHTML='';$('simulation').removeAttribute('src');$('simulation-note').textContent='Simulation has not started.';$('progress').value=0;tab('drawing');} $('empty').hidden=true;$('job').hidden=false;$('name').textContent=s.spec?.name||decodeURIComponent(s.filename||'Drawing');$('status').textContent=s.status.replaceAll('_',' ');$('message').textContent=s.message;$('message').className=['error','needs_input','failed'].includes(s.status)?'error':'';$('pdf-link').href=`/api/jobs/${s.id}/drawing.pdf`;
if(s.extracted_text&&$('preview').getAttribute('src')!==`/api/jobs/${s.id}/preview.png`)$('preview').src=`/api/jobs/${s.id}/preview.png`;
$('review').hidden=!['review','needs_input'].includes(s.status);document.querySelector('[data-tab=path]').disabled=!s.path_preview;document.querySelector('[data-tab=simulation]').disabled=!s.playback;
const stage=['uploaded','reading','interpreting'].includes(s.status)?'drawing':['review','needs_input','building_cad'].includes(s.status)?'review':['cam_planning','memory_updated'].includes(s.status)?'cam':s.status==='checks'?'checks':['completed','failed'].includes(s.status)?'result':'simulation';document.querySelectorAll('[data-stage]').forEach(e=>e.classList.toggle('active',e.dataset.stage===stage));
const spec=s.spec;if(spec){const review=spec.blockers.length?`<h2>Drawing needs attention</h2><ul>${spec.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p>Upload a revised supported drawing to continue.</p>`:`<h2>Confirm part</h2><p>${esc(spec.stock_kind)} stock · ${spec.stock_dimensions_mm.map(esc).join(' × ')} mm<br>Drawing tolerance: ${spec.drawing_tolerance_mm==null?'not specified':esc(spec.drawing_tolerance_mm)+' mm'}</p><table><tr><th>Feature</th><th>Radius</th><th>Floor Z</th></tr>${spec.features.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.radius_mm} mm</td><td>${f.floor_z_mm} mm</td></tr>`).join('')}</table><details><summary>Coordinates and drawing citations</summary><pre>${esc(JSON.stringify(spec.features,null,2))}</pre></details>${s.status==='review'?'<p class="micro">Review these dimensions. This run uses the fixed demo tool library and 3 mm geometric tolerance, not a tighter drawing tolerance.</p><button id="run">Run simulation · 3 mm demo</button>':''}`;$('review').innerHTML=review;const run=$('run');if(run)run.onclick=async()=>{run.disabled=true;const r=await fetch(`/api/jobs/${s.id}/run`,{method:'POST',body:'{}'}),d=await r.json();if(!r.ok)$('message').textContent=d.error;last='';refresh();};}
let outputs=spec?`<div class="output"><small>DRAWING INTERPRETATION · ASTRA</small>${esc(spec.summary)}</div>`:'';const rows=s.manifest?.attempts||[];for(const a of rows)outputs+=`<div class="output"><small>CANDIDATE ${a.index+1} · ${a.result.passed?'PASS':'FAIL'}</small>${esc(a.proposal.summary)}<details><summary>CAM parameters</summary><pre>${esc(JSON.stringify(a.strategy,null,2))}</pre></details>${a.result.issues.length?`<p class="error">${esc(a.result.issues.map(i=>i.description).join(' '))}</p>`:''}${a.judge?`<p>Judge: ${esc(a.judge.value.action)}. ${esc(a.judge.value.reason)}</p>`:''}</div>`;
if(s.proposal&&(!rows.length||JSON.stringify(rows.at(-1).strategy)!==JSON.stringify(s.proposal.strategy)))outputs+=`<div class="output"><small>GENERATED CAM · ${s.move_count} MOVEMENTS</small>${esc(s.proposal.summary)}<pre>${esc(JSON.stringify(s.proposal.strategy,null,2))}</pre></div>`;const agentHTML=outputs||'<p>Waiting for agent output…</p>';if($('agent').dataset.content!==agentHTML){$('agent').dataset.content=agentHTML;$('agent').innerHTML=agentHTML;}
$('activity').innerHTML=(s.manifest?.events||[]).slice(-20).map(e=>`<div class="activity"><time>${new Date(e.time*1000).toLocaleTimeString()}</time>${esc(e.message||e.type.replaceAll('_',' '))}</div>`).join('');
$('cam-summary').textContent=s.proposal?`${s.move_count} movements · ${s.proposal.summary}`:'';pathPreview(s.path_preview);const pathKey=s.id+JSON.stringify(s.proposal?.strategy||{});if(s.path_preview&&shownPath!==pathKey){shownPath=pathKey;tab('path');}if(s.simulation_progress){const p=s.simulation_progress;$('progress').value=Math.max(0,(p.move+1)/p.total_moves);$('simulation-note').textContent=`Computed movement ${p.move+1} / ${p.total_moves} · ${p.tool} · XYZ ${p.position.map(x=>x.toFixed(1)).join(', ')} mm. Replay appears after stock export.`;}
if(s.playback){if(shownPlayback!==s.playback){shownPlayback=s.playback;tab('simulation');}const replayURL=s.playback+'&ui=stock-fit-2';if($('simulation').getAttribute('src')!==replayURL)$('simulation').src=replayURL;$('simulation-note').textContent=(s.status==='completed'?'Best verified plan':'Completed candidate')+' · actual submitted cutter sweeps · accelerated replay.';if(s.status!=='simulating')$('progress').value=1;}
$('progress').hidden=s.status!=='simulating';const m=s.manifest||{},ref=m.reference?.result,b=m.best?.result,attempts=m.attempts||[];
const comparison=ref?.passed&&b?`${ref.estimated_time_seconds.toFixed(1)}s reference → ${b.estimated_time_seconds.toFixed(1)}s best · ${(100*(ref.estimated_time_seconds-b.estimated_time_seconds)/ref.estimated_time_seconds).toFixed(1)}% less machining time`:'';
$('loop-proof').innerHTML=attempts.length?`<div class="comparison">${esc(comparison)}</div><div class="attempt-strip">${attempts.map(a=>`<span class="${a.result.passed?'pass':'fail'}">${a.index+1} · ${a.result.passed?a.result.estimated_time_seconds.toFixed(1)+'s':'Failed'}</span>`).join('<span class="arrow">→</span>')}</div><details><summary>What changed?</summary><p>Loaded memory ${esc(m.loaded_memory_version??'—')}${s.memory_version?' · saved '+s.memory_version:''}. Each changed candidate is verified again.</p>${attempts.map(a=>`<p><b>Candidate ${a.index+1}</b> · ${esc(a.proposal.summary)}${a.result.issues.length?' '+esc(a.result.issues.map(i=>i.description).join(' ')):''}</p>`).join('')}<p>${esc(m.stop_reason||'Optimization running.')}</p><p>Reference savings measure CAM optimization. They do not establish that memory caused an improvement.</p></details>`:'';
if(m.telemetry?.readback_complete&&m.telemetry.url){const link=document.createElement('a');link.href=m.telemetry.url;link.target='_blank';link.textContent='Weave trace ↗';$('loop-proof').append(link);}const best=s.manifest?.best;$('result').innerHTML=best?`<h2>Verified plan</h2><div class="metric">${best.result.estimated_time_seconds.toFixed(1)}<small>estimated seconds</small></div><p class="micro">${s.memory_version?'Saved memory version '+s.memory_version:s.status==='error'?'Verified result retained after interruption.':'Optimization may still be running.'}</p><a href="/api/jobs/${s.id}/manifest.json" target="_blank">Full result JSON ↗</a> · <a href="/api/jobs/${s.id}/plan.json" target="_blank">Tool movements JSON ↗</a>`:'';
}
let refreshing=false,listMarkup='',loadedRevision='';
async function refresh(){
 if(refreshing)return;refreshing=true;
 try{
  const all=await fetch('/api/jobs?summary=1').then(r=>{if(!r.ok)throw Error('Jobs unavailable');return r.json();});
  const markup=all.map(s=>`<button class="jobitem ${s.id===selected?'active':''}" data-id="${s.id}">${esc(s.name||decodeURIComponent(s.filename||'Drawing'))}<small>${esc(s.status.replaceAll('_',' '))} · ${s.id.slice(0,4)}</small></button>`).join('');
  if(markup!==listMarkup){listMarkup=markup;$('jobs').innerHTML=markup;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.id;history.replaceState(null,'','?job='+selected);last='';tab('drawing');refresh();});}
  const id=selected,summary=all.find(s=>s.id===id),revision=summary?`${id}:${summary.updated_at}`:'';
  if(summary&&(!last||revision!==loadedRevision)){
   const response=await fetch(`/api/jobs/${id}`);if(!response.ok)throw Error('Job unavailable');const s=await response.json();
   if(selected===id){loadedRevision=revision;last=JSON.stringify(s);render(s);}
  }
 }finally{refreshing=false;}
}
refresh().catch(()=>$('message').textContent='Connecting to the local server…');
setInterval(()=>refresh().catch(()=>$('message').textContent='Connection lost. Jobs continue on the local server.'),1000);
